Caveman mode: **full**. Here go:

```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// --- Types ---
interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

// --- Component ---
class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // Log — swap console for Sentry/Datadog/etc.
    console.error("[ErrorBoundary]", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
      timestamp: new Date().toISOString(),
    });

    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    // Custom fallback takes priority
    if (fallback) return fallback(error, this.reset);

    return <DefaultFallback error={error} onRetry={this.reset} />;
  }
}

// --- Default fallback UI ---
function DefaultFallback({
  error,
  onRetry,
}: {
  error: Error;
  onRetry: () => void;
}) {
  return (
    <div role="alert" style={styles.container}>
      <span style={styles.icon}>⚠️</span>
      <h2 style={styles.title}>Something went wrong</h2>
      <p style={styles.message}>{error.message}</p>

      {/* Stack only in dev */}
      {process.env.NODE_ENV === "development" && (
        <pre style={styles.stack}>{error.stack}</pre>
      )}

      <button onClick={onRetry} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    padding: "2rem",
    gap: "1rem",
    fontFamily: "sans-serif",
    color: "#1a1a1a",
  },
  icon:    { fontSize: "3rem" },
  title:   { margin: 0, fontSize: "1.5rem" },
  message: { margin: 0, color: "#666", maxWidth: "40ch", textAlign: "center" },
  stack: {
    background: "#f5f5f5",
    padding: "1rem",
    borderRadius: "4px",
    fontSize: "0.75rem",
    maxWidth: "60ch",
    overflow: "auto",
    color: "#c0392b",
  },
  button: {
    padding: "0.5rem 1.5rem",
    background: "#0070f3",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    fontSize: "1rem",
  },
};

export default ErrorBoundary;
```

**Use:**

```tsx
// Basic
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary
  fallback={(error, retry) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={retry}>Retry</button>
    </div>
  )}
  onError={(err, info) => sendToSentry(err, info)}
>
  <MyComponent />
</ErrorBoundary>
```

---

**Key points:**

| Thing | Why |
|---|---|
| `getDerivedStateFromError` | Static — update state so render show fallback |
| `componentDidCatch` | Side effects only (log, report) — separate concern from state |
| `reset` arrow fn | Clears error → triggers re-render of children |
| Stack hide in prod | No leak internal paths to users |
| Custom `fallback` prop | Composable — each feature area own UI if needed |

**Gotcha:** Boundary no catch: async errors, event handlers, server-side errors. For those, use `try/catch` + `window.onerror` separately.
